// STREAMER LANDING PAGES
// Reads ?streamer=gnarly from URL and personalizes the login/register page
// Also handles ?ref= referral codes
// ═══════════════════════════════════════════════════════════════════════════

var _streamerLandingMember = null; // set if page loaded with ?streamer=

function streamerLanding_init() {
  var params = new URLSearchParams(window.location.search);
  var streamerParam = (params.get('streamer') || '').toLowerCase().trim();
  if (!streamerParam) return;

  // Match against TEAM_MEMBERS login or petName
  var member = TEAM_MEMBERS.find(function(m) {
    return m.login.toLowerCase() === streamerParam ||
           m.name.toLowerCase() === streamerParam ||
           m.petName.toLowerCase() === streamerParam;
  });
  if (!member) return;

  _streamerLandingMember = member;
  dbg('[Landing] Streamer landing page for:', member.name);

  // Auto-populate ref code if streamer has one stored in DB
  // (we'll store it in localStorage so registration picks it up)
  streamerLanding_buildHero(member);

  // If a referral code is attached to the URL, store it
  var refCode = params.get('ref');
  if (refCode) {
    localStorage.setItem('pendingRefCode', refCode);
  }
}

function streamerLanding_buildHero(member) {
  // Map pet names to their actual filenames (some differ from lowercase petName)
  var _petImgMap = {
    'Ember':'ember.png','Pyxie':'pyxie.png','Aria':'aria.png',
    'Blushimia':'blushimia.png','Steve':'cowbee.png','Kleat':'kelta.png',
    'Jess':'jess.png','Gnarly':'gnarly.png','Cypurr':'cy.png'
  };
  var petImageFile = _petImgMap[member.petName] || (member.petName.toLowerCase() + '.png');
  var accent = member.accentColor || '#9966ff';
  var bg = member.bgGradient || 'linear-gradient(135deg,#1a0a2e 0%,#0a0a1a 100%)';

  // Build social links
  var socialHTML = '';
  if (member.socialLinks && member.socialLinks.length > 0) {
    socialHTML = '<div class="streamer-landing-socials">' +
      member.socialLinks.map(function(link) {
        return '<a href="' + escapeHtml(link.url) + '" target="_blank" rel="noopener" ' +
               'class="streamer-landing-social-btn" ' +
               'style="border-color:' + accent + ';color:' + accent + ';">' +
               escapeHtml(link.icon) + ' ' + escapeHtml(link.label) + '</a>';
      }).join('') + '</div>';
  }

  var heroHTML =
    '<div class="landing-hero streamer-landing-hero" ' +
         'style="background:' + bg + ';border-radius:20px;padding:28px 20px 24px;margin-bottom:20px;' +
                'border:2px solid ' + accent + ';box-shadow:0 8px 32px rgba(0,0,0,0.4);">' +
      '<div class="streamer-landing-pet-wrap">' +
        '<img src="images/pets/' + petImageFile + '" ' +
             'alt="' + escapeHtml(member.petName) + '" ' +
             'class="streamer-landing-pet-img" ' +
             'style="filter:drop-shadow(0 0 20px ' + accent + ');" ' +
             'onerror="this.src=&quot;images/logo.png&quot;" />' +
      '</div>' +
      '<div class="streamer-landing-info">' +
        '<div class="streamer-landing-invited" style="color:rgba(255,255,255,0.65);">' +
          '<span class="streamer-landing-dot" style="background:' + accent + ';flex-shrink:0;"></span>' +
          '<span>' + escapeHtml(member.name) + ' invited you to PawketPets<span style="color:' + accent + ';">VT</span>!</span>' +
        '</div>' +
        '<h1 class="landing-title" style="font-size:1.9rem;margin:10px 0 6px;color:#fff;' +
            'text-shadow:0 2px 12px ' + accent + ';">' +
          'Adopt <span style="color:' + accent + ';">' + escapeHtml(member.petName) + '</span>!' +
        '</h1>' +
        (member.bio
          ? '<p style="font-size:0.84rem;color:rgba(255,255,255,0.65);line-height:1.6;margin:0 0 12px;max-width:340px;">' +
              escapeHtml(member.bio) + '</p>'
          : '') +
        '<p style="font-size:0.82rem;color:rgba(255,255,255,0.45);margin:0 0 14px;">' +
          'Free to play \u00b7 Your first pet is on us!' +
        '</p>' +
        '<div class="streamer-landing-links">' +
          '<a href="' + escapeHtml(member.twitchUrl) + '" target="_blank" rel="noopener" ' +
             'class="streamer-landing-twitch-btn" ' +
             'style="background:' + accent + ';box-shadow:0 4px 14px ' + accent + '80;">' +
            '\u{1F3AE} Watch ' + escapeHtml(member.name) + ' on Twitch' +
          '</a>' +
        '</div>' +
        socialHTML +
      '</div>' +
    '</div>';

  // Apply to both auth sections
  ['section-login', 'section-register'].forEach(function(sectionId) {
    var section = document.getElementById(sectionId);
    if (!section) { dbg('[Landing] Section not found:', sectionId); return; }
    var existingHero = section.querySelector('.landing-hero');
    if (existingHero) {
      existingHero.outerHTML = heroHTML;
      dbg('[Landing] Hero replaced in', sectionId, 'for', member.name);
    } else {
      dbg('[Landing] .landing-hero not found in', sectionId);
    }
  });

  // Set accent CSS variable for streamer-themed form card borders etc.
  document.body.style.setProperty('--streamer-accent', accent);
  document.body.classList.add('streamer-landing-active');

  // Show register tab for new visitors
  showAuthSection('register');
}

async function streamerLanding_checkLive(member) {
  // Check if this streamer is currently live and add indicator
  if (!member) return;
  var liveStreamer = _currentlyLiveStreamers.find(function(s) {
    return s.login.toLowerCase() === member.login.toLowerCase();
  });

  var dot = document.querySelector('.streamer-landing-dot');
  var inviteEl = document.querySelector('.streamer-landing-invited');
  if (!dot || !inviteEl) return;

  if (liveStreamer) {
    dot.style.background = '#ff4444';
    dot.style.animation = 'live-dot-pulse 1.4s ease-in-out infinite';
    dot.style.boxShadow = '0 0 6px #ff4444';
    inviteEl.innerHTML = '<span class="streamer-landing-dot" style="background:#ff4444;animation:live-dot-pulse 1.4s ease-in-out infinite;box-shadow:0 0 6px #ff4444;"></span>' +
      escapeHtml(member.name) + ' is <strong style="color:#ff4444;">LIVE RIGHT NOW</strong>, check them out!';
  }
}

async function loadTeamShowcase() {
  var showcase = document.getElementById('team-showcase');
  if (!showcase) return;
  showcase.innerHTML = '';

  // Check live status for each member using Twitch API if user has linked their account
  // Falls back to showing static cards if not linked
  var liveData = {};
  try {
    var user = currentUser;
    if (user) {
      var pr = await supabaseClient.from('players').select('twitch_token').eq('id', user.id).maybeSingle();
      if (pr.data && pr.data.twitch_token) {
        var logins = TEAM_MEMBERS.map(function(m){ return 'user_login='+m.login; }).join('&');
        var resp = await fetch('https://api.twitch.tv/helix/streams?' + logins, {
          headers: { 'Client-Id': TWITCH_CLIENT_ID, 'Authorization': 'Bearer ' + pr.data.twitch_token }
        });
        var data = await resp.json();
        if (data.data) {
          data.data.forEach(function(stream) {
            liveData[stream.user_login.toLowerCase()] = {
              live: true,
              viewers: stream.viewer_count,
              title: stream.title
            };
          });
        }
      }
    }
  } catch(e) { dbg('Could not check live status:', e); }

  TEAM_MEMBERS.forEach(function(member) {
    var card = document.createElement('div');
    card.className = 'team-member-card';

    // Avatar with pet image (lowercase filenames)
    var avatarDiv = document.createElement('div');
    avatarDiv.className = 'team-avatar';
    
    // Map pet names to lowercase image filenames
    var petImageMap = {
      'Ember': 'ember.png',
      'Pyxie': 'pyxie.png',
      'Aria': 'aria.png',
      'Blushimia': 'blushimia.png',
      'Steve': 'cowbee.png',
      'Kleat': 'kelta.png',
      'Jess': 'jess.png',
      'Gnarly': 'gnarly.png',
      'Cypurr': 'cy.png'
    };
    
    var imageName = petImageMap[member.petName] || member.petName.toLowerCase() + '.png';
    var imgSrc = 'images/pets/' + imageName;
    
    var img = document.createElement('img');
    img.src = imgSrc;
    img.alt = member.name;
    img.style.cssText = 'width:100%;height:100%;object-fit:cover;';
    img.onerror = function() {
      // Fallback to letter if image fails
      this.style.display = 'none';
      avatarDiv.style.cssText = 'display:flex;align-items:center;justify-content:center;font-family:Fredoka One,cursive;font-size:2rem;color:var(--purple-dark);background:var(--purple-light);';
      avatarDiv.textContent = member.name.charAt(0);
    };
    
    avatarDiv.appendChild(img);
    card.appendChild(avatarDiv);

    card.appendChild(makeEl('div', {class:'team-name'}, member.name));

    var liveStatus = liveData[member.login.toLowerCase()];
    var badge = makeEl('span', {class: liveStatus ? 'team-live-badge live' : 'team-live-badge offline'});
    badge.textContent = liveStatus ? '&#128308; LIVE' : 'Offline';
    badge.innerHTML = liveStatus ? '&#128308; LIVE' : 'Offline';
    card.appendChild(badge);

    if (liveStatus && liveStatus.viewers) {
      card.appendChild(makeEl('div', {class:'team-viewers'}, liveStatus.viewers.toLocaleString() + ' viewers'));
    }

    if (liveStatus && liveStatus.title) {
      var title = makeEl('div', {style:'font-size:0.78rem;color:var(--text-light);line-height:1.3;max-height:36px;overflow:hidden;'});
      title.textContent = liveStatus.title;
      card.appendChild(title);
    }

    var watchBtn = makeEl('a', {href:member.twitchUrl, target:'_blank', class:'btn-watch'}, 'Watch on Twitch');
    card.appendChild(watchBtn);

    showcase.appendChild(card);
  });
}
async function checkTwitchLinked() {
  if(!currentUser)return;
  var res=await supabaseClient.from('players').select('twitch_username,twitch_id,twitch_token,twitch_follow_rewards').eq('id',currentUser.id).single();
  if(res.data&&res.data.twitch_username){
    el('twitch-not-linked').style.display='none';
    el('twitch-linked').style.display='block';
    el('twitch-username').textContent=res.data.twitch_username;
    loadTwitchStats().then(null, function(){});
    var rewards=res.data.twitch_follow_rewards||{};
    if(rewards.embertail){var b=el('follow-ember-badge');b.textContent='Claimed';b.className='status-badge status-done';b.style.display='inline-block';}
    if(rewards.pyxshuul){var b2=el('follow-pyxs-badge');b2.textContent='Claimed';b2.className='status-badge status-done';b2.style.display='inline-block';}
  }
}

async function checkFollows() {
  var btn=el('check-follows-btn'); btn.disabled=true; btn.textContent='Checking...';
  if(!currentUser)return;
  var pr=await supabaseClient.from('players').select('twitch_id,twitch_token,pawketpoints,twitch_follow_rewards').eq('id',currentUser.id).single();
  if(!pr.data||!pr.data.twitch_token){showToast('Twitch not linked!');btn.disabled=false;btn.textContent='Check Follows';return;}
  var twitchId=pr.data.twitch_id; var token=pr.data.twitch_token;
  var rewards=pr.data.twitch_follow_rewards||{}; var earned=0;
  for(var key in STREAMER_IDS){
    if(rewards[key])continue;
    var sid=STREAMER_IDS[key]; if(sid.indexOf('TWITCH_USER_ID')!==-1)continue;
    try{
      var fr=await fetch('https://api.twitch.tv/helix/channels/followed?user_id='+twitchId+'&broadcaster_id='+sid,{headers:{'Client-Id':TWITCH_CLIENT_ID,'Authorization':'Bearer '+token}});
      var fd=await fr.json();
      if(fd.data&&fd.data.length>0){
        rewards[key]=true; earned+=50;
        var b=el('follow-'+key+'-badge');
        if(b){b.textContent='Claimed';b.className='status-badge status-done';b.style.display='inline-block';}
      } else {
        var b2=el('follow-'+key+'-badge');
        if(b2){b2.textContent='Not following';b2.className='status-badge status-pending';b2.style.display='inline-block';}
      }
    }catch(e){console.warn('Follow check error',key,e);}
  }
  var np = 0;
  if (earned > 0) {
    var { data: newPp, error: ppErr } = await supabaseClient.rpc('award_pp_secure', {
      p_amount: earned, p_reason: 'twitch_follow'
    });
    if (ppErr) { dbg('Twitch follow PP award failed:', ppErr); }
    else np = newPp;
  }
  // twitch_follow_rewards is just a tracking flag, not a currency/stat field — safe to write directly
  await supabaseClient.from('players').update({ twitch_follow_rewards: rewards }).eq('id', currentUser.id);
  if(earned>0){updateAllPoints(np);showToast('You earned '+earned+' PP!');}
  else showToast('No new rewards. Follow our streamers!');
  btn.disabled=false; btn.textContent='Check Follows & Claim Rewards';
}

async function unlinkTwitch(){
  if(!currentUser)return;
  await supabaseClient.from('players').update({twitch_id:null,twitch_username:null,twitch_token:null}).eq('id',currentUser.id);
  el('twitch-not-linked').style.display='block';
  el('twitch-linked').style.display='none';
  showToast('Twitch unlinked.');
}
// ── REDEEM CODES ─────────────────────────────

// ── Ambient Pet Name Glitches ───────────────────────────────────────────────
// Rare, per-pet-card chance for a name to briefly glitch to a creepy alt-text,
// then revert. Independent per card — never affects every pet on the page at once.
// Fully gated behind playerSettings.spooky_enabled so players who opt out never see it.
var SPOOKY_NAME_GLITCH_CHANCE = 0.015; // ~1.5% chance per card render
var SPOOKY_NAME_ALTS = ['HelpMe', 'LetMeOut', 'ItSeesYou', 'NotAlone', 'BehindYou', 'StillHere', 'TooLate'];

function maybeApplyNameGlitch(el, originalText) {
  if (!playerSettings.spooky_enabled) return;
  if (!el || Math.random() >= SPOOKY_NAME_GLITCH_CHANCE) return;

  var altText = SPOOKY_NAME_ALTS[Math.floor(Math.random() * SPOOKY_NAME_ALTS.length)];
  var durationMs = 5000 + Math.random() * 5000; // 5-10 seconds

  el.classList.add('glitch-text');
  el.textContent = altText;

  safeSetTimeout(function() {
    if (el && el.isConnected) {
      el.classList.remove('glitch-text');
      el.textContent = originalText;
    }
  }, durationMs);
}

// ── Ambient UI Element Glitches ─────────────────────────────────────────────
// Very rarely, UI panels or nav buttons briefly shift/distort then snap back.
// Purely CSS-class driven — no DOM mutations, fully reversible.
var SPOOKY_UI_GLITCH_CHANCE = 0.004; // ~0.4% per 8 second check = roughly once per 30 mins active
var SPOOKY_UI_TARGETS = [
  '.sidebar-nav-btn', '.form-card', '.pet-card',
  '.battle-area', '.tab-content-inner', '.shop-grid'
];

safeSetInterval(function() {
  if (!playerSettings.spooky_enabled) return;
  if (Math.random() >= SPOOKY_UI_GLITCH_CHANCE) return;

  // Pick a random target class and find a visible element
  var targetClass = SPOOKY_UI_TARGETS[Math.floor(Math.random() * SPOOKY_UI_TARGETS.length)];
  var candidates = Array.from(document.querySelectorAll(targetClass)).filter(function(el) {
    var rect = el.getBoundingClientRect();
    return rect.width > 0 && rect.top >= 0 && rect.bottom <= window.innerHeight;
  });
  if (candidates.length === 0) return;

  var target = candidates[Math.floor(Math.random() * candidates.length)];
  if (target.dataset.spookyGlitching) return; // already glitching

  target.dataset.spookyGlitching = '1';
  target.classList.add('spooky-ui-glitch');

  // Remove after 0.6–1.2 seconds
  safeSetTimeout(function() {
    target.classList.remove('spooky-ui-glitch');
    delete target.dataset.spookyGlitching;
  }, 600 + Math.random() * 600);
}, 8000);

// ── Ambient Spinner Caption Glitches ────────────────────────────────────────
// Periodically scans the page for visible loading spinners and rarely attaches
// a brief unsettling caption beneath one, then removes it. Purely additive —
// doesn't require touching any of the 45 existing spinner call sites.
var SPOOKY_SPINNER_GLITCH_CHANCE = 0.02; // ~2% chance per scan, per spinner found
var SPOOKY_SPINNER_CAPTIONS = ['loading you...', 'almost there...', 'it sees you waiting', 'please wait forever', 'fetching something else'];

safeSetInterval(function() {
  if (!playerSettings.spooky_enabled) return;
  var spinners = document.querySelectorAll('.spinner');
  if (spinners.length === 0) return;

  spinners.forEach(function(spinner) {
    if (spinner.dataset.spookyActive) return; // don't stack multiple captions on one spinner
    if (Math.random() >= SPOOKY_SPINNER_GLITCH_CHANCE) return;

    spinner.dataset.spookyActive = '1';
    var caption = document.createElement('div');
    caption.className = 'glitch-text';
    caption.textContent = SPOOKY_SPINNER_CAPTIONS[Math.floor(Math.random() * SPOOKY_SPINNER_CAPTIONS.length)];
    caption.style.cssText = 'font-size:0.72rem;text-align:center;margin-top:6px;';
    if (spinner.parentNode) spinner.parentNode.insertBefore(caption, spinner.nextSibling);

    safeSetTimeout(function() {
      if (caption.parentNode) caption.parentNode.removeChild(caption);
      delete spinner.dataset.spookyActive;
    }, 2500 + Math.random() * 2500); // 2.5-5 seconds, spinners are usually short-lived anyway
  });
}, 4000); // check every 4 seconds

// Clean up any leftover spooky effects on page load
function piperShop_open() {
  // Piper's shop — ARG feature, not yet fully implemented.
  // Silently do nothing if triggered before unlock; the button stays display:none until unlocked.
  var modal = document.getElementById('piper-shop-modal');
  if (modal) modal.classList.add('show');
}

function closeCreepyPopup() {
  // Close the Piper ARG creepy popup overlay
  var popup = document.getElementById('creepy-popup');
  if (popup) popup.style.display = 'none';
}

function cleanupSpookyEffects() {
  var overlay = document.getElementById('spooky-overlay');
  if (overlay && overlay.parentNode) {
    overlay.parentNode.removeChild(overlay);
  }
  
  // Remove any CRT scanline divs
  var allDivs = document.querySelectorAll('div');
  for (var i = 0; i < allDivs.length; i++) {
    var div = allDivs[i];
    if (div.style.animation && div.style.animation.includes('crt-flicker')) {
      if (div.parentNode) div.parentNode.removeChild(div);
    }
  }
  
  dbg('✨ Cleaned up spooky effects');
}

// ── CORRUPTION VISUAL EFFECTS ───────────────────────────────────────────────
// Three tiers, driven by world_state_flags.corruption_level (0-100):
//   ≤ 25 : no effect — world looks pristine
//   25-75: occasional glitchy pixel flashes (rare, not constant)
//   ≥ 75 : dark purple overlay + heavier glitch aesthetic site-wide
//
// Reads _worldStateCache (sync, no extra DB calls).
// Applies body classes: corruption-mid | corruption-high.
// Safe to add/remove at any time — fully CSS-driven, no DOM mutations.
// ────────────────────────────────────────────────────────────────────────────

var _corruptionVisualsLastLevel = -1;

function corruptionVisuals_apply(level) {
  var body = document.body;
  if (!body) return;

  if (level >= 75) {
    body.classList.remove('corruption-mid');
    body.classList.add('corruption-high');
  } else if (level >= 25) {
    body.classList.remove('corruption-high');
    body.classList.add('corruption-mid');
  } else {
    body.classList.remove('corruption-mid', 'corruption-high');
  }
}

// Poll the sync cache every 30s — only re-applies if level has changed
safeSetInterval(function() {
  var level = getWorldStateValueSync('corruption_level', 50);
  if (level === _corruptionVisualsLastLevel) return;
  _corruptionVisualsLastLevel = level;
  corruptionVisuals_apply(level);
}, 30000);

// Also apply immediately after world state loads (called from showApp)
function corruptionVisuals_init() {
  var level = getWorldStateValueSync('corruption_level', 50);
  _corruptionVisualsLastLevel = level;
  corruptionVisuals_apply(level);
}

// Mid-tier: occasional random pixel flash on a random element (25-75%)
// Only fires during corruption-mid, at a low rate (~once per ~45s avg)
safeSetInterval(function() {
  if (!document.body.classList.contains('corruption-mid')) return;
  if (Math.random() > 0.50) return; // 50% chance each 5s tick

  var candidates = Array.from(document.querySelectorAll(
    '.pet-card, .sidebar-nav-btn, .form-card, .shop-card, .today-card'
  )).filter(function(el) {
    var r = el.getBoundingClientRect();
    return r.width > 0 && r.top >= 0 && r.bottom <= window.innerHeight;
  });
  if (!candidates.length) return;

  var target = candidates[Math.floor(Math.random() * candidates.length)];
  if (target.dataset.corruptGlitching) return;
  target.dataset.corruptGlitching = '1';
  target.classList.add('corruption-glitch-flash');
  safeSetTimeout(function() {
    target.classList.remove('corruption-glitch-flash');
    delete target.dataset.corruptGlitching;
  }, 400 + Math.random() * 300);
}, 5000);

// Spooky effect for THEYWENTMISSING code
function triggerSpookyEffect() {
  // Add dark overlay with CRT effect
  var overlay = document.createElement('div');
  overlay.id = 'spooky-overlay';
  overlay.style.cssText = `
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.85);
    z-index: 9998;
    pointer-events: none;
    animation: spooky-fade-in 1s ease-in;
  `;
  
  // Add CRT scanlines effect
  var crtLines = document.createElement('div');
  crtLines.style.cssText = `
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: repeating-linear-gradient(
      0deg,
      rgba(0, 0, 0, 0.15),
      rgba(0, 0, 0, 0.15) 1px,
      transparent 1px,
      transparent 2px
    );
    z-index: 9999;
    pointer-events: none;
    animation: crt-flicker 0.1s infinite;
  `;
  
  document.body.appendChild(overlay);
  document.body.appendChild(crtLines);
  
    // Show Piper melody indicator on mobile (more visible than glitch effects)
    if (window.innerWidth < 768) {
      var _existBanner = document.getElementById('piper-melody-banner');
      if (!_existBanner) {
        var _b = document.createElement('div');
        _b.id = 'piper-melody-banner';
        _b.style.cssText = 'position:fixed;top:0;left:0;right:0;padding:10px;text-align:center;background:rgba(80,0,120,0.92);color:#e8d5ff;font-weight:900;font-size:1.05rem;z-index:10010;letter-spacing:1px;';
        _b.textContent = '?? PIPER’S MELODY — YOU SHOULDN’T BE HERE ??';
        document.body.appendChild(_b);
        setTimeout(function(){ if (_b.parentNode) _b.parentNode.removeChild(_b); }, 2500);
      }
    }
  // Play spooky audio (Piper's flute) — load on-demand since bossNormal isn't in the priority preload list
  try {
    var piperKey = 'bossNormal';
    var spookyAudioSrc = audioCache[piperKey] || loadSoundOnDemand(piperKey);
    if (spookyAudioSrc) {
      var spookyAudio = spookyAudioSrc.cloneNode();
      spookyAudio.volume = 0.3;
      spookyAudio.play().catch(function(err) {
        dbg('Spooky audio failed to play:', err);
      });
    } else {
      dbg('Spooky audio unavailable — sound file missing or SOUNDS_ENABLED is false');
    }
  } catch (err) {
    dbg('Could not load spooky audio');
  }
  
  // Remove effects after 3 seconds
  safeSetTimeout(function() {
    overlay.style.animation = 'spooky-fade-out 1s ease-out';
    crtLines.style.animation = 'spooky-fade-out 1s ease-out';
    safeSetTimeout(function() {
      if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
      if (crtLines.parentNode) crtLines.parentNode.removeChild(crtLines);
    }, 1000);
  }, 3000);
  
  // Trigger Melon's spooky dialogue if on shop page (check safely)
  var shopSection = document.getElementById('section-shop');
  if (shopSection && shopSection.classList.contains('active')) {
    setTimeout(function() {
      if (typeof showSpookyDialogue === 'function') {
        showSpookyDialogue();
      }
    }, 1000);
  }
}

// Update the points counter in the redeem tab too
// We need to patch updateAllPoints to include redeem-points.
// Find your updateAllPoints function and add 'redeem-points' to the forEach array like this:
//   ['adopt-points','mypets-points','shop-points','games-points','redeem-points']

async function redeemCode() {
  if (!currentUser) return;
  var input = el('redeem-code-input');
  var btn   = el('redeem-btn');
  var errEl = el('redeem-error');
  var successPanel = el('redeem-success-panel');
  var code  = input.value.trim().toUpperCase();

  // Reset state
  errEl.classList.remove('show');
  errEl.textContent = '';
  successPanel.style.display = 'none';

  if (!code) {
    errEl.textContent = 'Please enter a code!';
    errEl.classList.add('show');
    return;
  }

  btn.textContent = 'Checking...';
  btn.disabled = true;

  try {
    // 1. Look up the promo code (case-insensitive via upper())
    var codeRes = await supabaseClient
      .from('promo_codes')
      .select('id, code, pp_reward, lore_page, description, max_uses, times_used, is_active')
      .eq('code', code)
      .eq('is_active', true)
      .maybeSingle();

    if (codeRes.error || !codeRes.data) {
      errEl.textContent = 'That code doesn\'t exist or is no longer active. Check for typos!';
      errEl.classList.add('show');
      btn.textContent = '✨ Redeem!';
      btn.disabled = false;
      return;
    }

    var promo = codeRes.data;

    // CHECK: Block spooky codes if setting is OFF
    if (code === 'THEYWENTMISSING' && !playerSettings.spooky_enabled) {
      errEl.textContent = '👻 Your in-game settings prevent you from seeing this content.';
      errEl.classList.add('show');
      btn.textContent = '✨ Redeem!';
      btn.disabled = false;
      return;
    }

    // 2. Check max uses
    if (promo.max_uses !== null && promo.times_used >= promo.max_uses) {
      errEl.textContent = 'This code has been fully claimed, sorry!';
      errEl.classList.add('show');
      btn.textContent = '✨ Redeem!';
      btn.disabled = false;
      return;
    }

    // 3. Check if THIS player already redeemed it.
    // THEYWENTMISSING is a lore discovery code — skip so players can re-trigger the effect.
    if (code !== 'THEYWENTMISSING') {
      var alreadyRes = await supabaseClient
        .from('redeemed_codes')
        .select('id')
        .eq('player_id', currentUser.id)
        .eq('code_id', promo.id)
        .maybeSingle();

      if (alreadyRes.data) {
        errEl.textContent = 'You\'ve already redeemed this code! Each code is one per account.';
        errEl.classList.add('show');
        btn.textContent = '\u2728 Redeem!';
        btn.disabled = false;
        return;
      }
    }

    // 4. All good — award the PP
    if (promo.pp_reward && promo.pp_reward > 0) {
      var { data: newPoints, error: ppErr } = await supabaseClient.rpc('award_pp_secure', {
        p_amount: promo.pp_reward, p_reason: 'promo_code_' + code
      });
      if (ppErr) throw new Error(ppErr.message);
      updateAllPoints(newPoints);
    }

    // 5. Log the redemption in redeemed_codes — always, so the per-player check above works correctly
    await supabaseClient.from('redeemed_codes').insert([{
      player_id: currentUser.id,
      code_id: promo.id,
      redeemed_at: new Date().toISOString()
    }]);

    // 6. Increment times_used on promo_codes
    await supabaseClient
      .from('promo_codes')
      .update({ times_used: (promo.times_used || 0) + 1 })
      .eq('id', promo.id);

    // 6.5. SPOOKY EFFECT for THEYWENTMISSING code - BEFORE showing success panel
    if (code === 'THEYWENTMISSING') {
      triggerSpookyEffect();
      // Wait for spooky effect to complete before showing success
      await new Promise(resolve => setTimeout(resolve, 3000));
    }

    // 7. Show success panel
    input.value = '';
    successPanel.style.display = 'block';

    var titleEl = el('redeem-success-title');
    var msgEl   = el('redeem-success-msg');
    var loreBtn = el('redeem-lore-btn');

    // 8. If it's a lore code (spooky easter egg), show the lore button
    if (promo.lore_page) {
      titleEl.textContent = '...';
      msgEl.textContent = ''; // No description shown
      loreBtn.style.display = 'inline-block';
      loreBtn.href = promo.lore_page;
      loreBtn.textContent = '🔍 Something feels... off. Click here.';
    } else {
      // Normal reward codes
      if (promo.pp_reward && promo.pp_reward > 0) {
        titleEl.textContent = '+' + promo.pp_reward + ' PawketPoints!';
        msgEl.textContent = promo.description || 'Code redeemed successfully!';
      } else {
        titleEl.textContent = 'Code Accepted.';
        msgEl.textContent = promo.description || 'Something has been unlocked...';
      }
      loreBtn.style.display = 'none';
    }

    // Reload history
    loadRedeemHistory();
    showToast('Code redeemed! 🎉');

  } catch(err) {
    errEl.textContent = 'Something went wrong: ' + err.message;
    errEl.classList.add('show');
  }

  btn.textContent = '✨ Redeem!';
  btn.disabled = false;
}

async function loadRedeemHistory() {
  var container = el('redeem-history');
  if (!currentUser) return;
  container.innerHTML = '<div class="spinner"></div>';

  var res = await supabaseClient
    .from('redeemed_codes')
    .select('redeemed_at, code_id, promo_codes(code, pp_reward, description)')
    .eq('player_id', currentUser.id)
    .order('redeemed_at', { ascending: false })
    .limit(10);

  if (res.error || !res.data || !res.data.length) {
    container.innerHTML = '<div class="redeem-empty">No codes redeemed yet!<br>Check streams and socials for codes. 🎟</div>';
    return;
  }

  container.innerHTML = '';
  res.data.forEach(function(row) {
    var promo = row.promo_codes || {};
    var date  = new Date(row.redeemed_at).toLocaleDateString('en-US', { year:'numeric', month:'short', day:'numeric' });
    var item  = document.createElement('div');
    item.className = 'redeem-history-item';
    item.innerHTML =
      '<span class="rhi-code">🎟 ' + (promo.code || '???') + '</span>' +
      '<span style="flex:1;padding:0 12px;font-size:0.82rem;color:var(--text-light);">' + (promo.description || '') + '</span>' +
      (promo.pp_reward ? '<span class="rhi-pp">+' + promo.pp_reward + ' PP</span>' : '<span class="rhi-pp" style="color:var(--purple)">🔍 Lore</span>') +
      '<span class="rhi-date" style="margin-left:12px;">' + date + '</span>';
    container.appendChild(item);
  });
}


