// Check for referral code on signup
async function checkReferralCode() {
  var urlParams = new URLSearchParams(window.location.search);
  var refCode = urlParams.get('ref');
  
  if (!refCode) return;
  
  // Store referral code for signup
  localStorage.setItem('pendingReferralCode', refCode);
  dbg('[Referral] Referral code detected:', refCode);
}

// Process referral after first pet adoption
async function processReferral() {
  var refCode = localStorage.getItem('pendingReferralCode');
  
  if (!refCode || !currentUser) return;
  
  try {
    // Find referrer
    var { data: referrer, error } = await supabaseClient
      .from('players')
      .select('id, username, referral_count')
      .eq('referral_code', refCode)
      .maybeSingle();
    
    if (error || !referrer) {
      dbg('[Referral] Referrer not found');
      localStorage.removeItem('pendingReferralCode');
      return;
    }
    
    // Don't allow self-referral
    if (referrer.id === currentUser.id) {
      dbg('[Referral] Cannot refer yourself');
      localStorage.removeItem('pendingReferralCode');
      return;
    }
    
    // Award referrer
    var referralLabel = currentUser.user_metadata?.username || currentUser.email?.split('@')[0] || 'a new player';
    await supabaseClient.rpc('award_pp_to_user_secure', {
      p_target_user_id: referrer.id,
      p_amount: 250,
      p_reason: 'referral_milestone'
    }).then(null, function(){});
    
    // Increment referral count
    await supabaseClient
      .from('players')
      .update({ referral_count: (referrer.referral_count || 0) + 1 })
      .eq('id', referrer.id);
    
    // Notify referrer
    await createNotification(
      referrer.id,
      'referral_reward',
      '💰 Referral Bonus!',
      'Your friend joined PawketPetsVT! +250 PP',
      'tab:stats'
    );
    
    // Clear pending referral
    localStorage.removeItem('pendingReferralCode');
    
    dbg('✅ Referral processed for:', referrer.username);
    showToast('Welcome! Your friend has been credited with a referral bonus! 🎉');
    
  } catch (err) {
    console.error('[Referral] Error processing:', err);
  }
}


